/* @autogenerated */
package net.civeira.phylax.feature.oauth.device.infrastructure.driven;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.time.temporal.ChronoUnit;
import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;

import net.civeira.phylax.feature.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.feature.oauth.device.domain.DeviceAuthorization;
import net.civeira.phylax.feature.oauth.device.domain.DeviceAuthorizationStatus;
import net.civeira.phylax.testing.sql.H2Database;

/** The device grant (RFC 8628) codes stored with the production sql on an h2 database. */
class DeviceAuthorizationSqlAdapterUnitTest {
  private DeviceAuthorizationSqlAdapter adapter;

  @BeforeEach
  void setUp() {
    adapter = new DeviceAuthorizationSqlAdapter(new H2Database().dataSource(),
        new ObjectMapper().findAndRegisterModules()
            .configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false));
  }

  private DeviceAuthorization pending(String deviceCode, String userCode) {
    OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC).truncatedTo(ChronoUnit.SECONDS);
    return DeviceAuthorization.builder().deviceCode(deviceCode).userCode(userCode).tenant("acme")
        .clientId("tv").scope("openid profile").audiences(List.of("api")).interval(5)
        .requestedAt(now).expiresAt(now.plusMinutes(10)).status(DeviceAuthorizationStatus.PENDING)
        .build();
  }

  @Test
  @DisplayName("A device code is stored and found by its device and user codes")
  void stored_and_found() {
    adapter.create(pending("device-1", "USER-1"));

    DeviceAuthorization found = adapter.findByDeviceCode("device-1").orElseThrow();
    Assertions.assertEquals("USER-1", found.getUserCode());
    Assertions.assertEquals("acme", found.getTenant());
    Assertions.assertEquals("tv", found.getClientId());
    Assertions.assertEquals("openid profile", found.getScope());
    Assertions.assertEquals(List.of("api"), found.getAudiences());
    Assertions.assertEquals(5, found.getInterval());
    Assertions.assertEquals(DeviceAuthorizationStatus.PENDING, found.getStatus());
    Assertions.assertTrue(found.getAuth().isEmpty(), "Nobody has approved it yet");
    Assertions.assertFalse(found.isExpired());
    Assertions.assertTrue(adapter.findByUserCode("acme", "USER-1").isPresent());
    Assertions.assertTrue(adapter.findByUserCode("other", "USER-1").isEmpty(),
        "The user code is only valid on its tenant");
    Assertions.assertTrue(adapter.findByDeviceCode("missing").isEmpty());
  }

  @Test
  @DisplayName("A pending code is approved once, with the authentication of the user")
  void approve_once() {
    adapter.create(pending("device-1", "USER-1"));
    AuthenticationData auth = new AuthenticationData();
    auth.setUid("user-uid");
    auth.setUsername("alice");

    Assertions.assertTrue(adapter.approve("device-1", auth));
    Assertions.assertFalse(adapter.approve("device-1", auth), "An approved code is not pending");
    Assertions.assertFalse(adapter.deny("device-1"), "An approved code can not be denied");

    DeviceAuthorization found = adapter.findByDeviceCode("device-1").orElseThrow();
    Assertions.assertEquals(DeviceAuthorizationStatus.APPROVED, found.getStatus());
    Assertions.assertEquals("alice", found.getAuth().orElseThrow().getUsername());
  }

  @Test
  @DisplayName("A pending code can be denied")
  void deny() {
    adapter.create(pending("device-1", "USER-1"));

    Assertions.assertTrue(adapter.deny("device-1"));
    Assertions.assertEquals(DeviceAuthorizationStatus.DENIED,
        adapter.findByDeviceCode("device-1").orElseThrow().getStatus());
    Assertions.assertFalse(adapter.approve("device-1", new AuthenticationData()));
  }

  @Test
  @DisplayName("The polls are recorded and a slow down increases the interval")
  void polls() {
    adapter.create(pending("device-1", "USER-1"));
    OffsetDateTime now = OffsetDateTime.now(ZoneOffset.UTC).truncatedTo(ChronoUnit.SECONDS);

    adapter.touchPoll("device-1", now);
    Assertions
        .assertTrue(adapter.findByDeviceCode("device-1").orElseThrow().getLastPollAt().isPresent());

    adapter.slowDown("device-1", now.plusSeconds(1));
    Assertions.assertEquals(10, adapter.findByDeviceCode("device-1").orElseThrow().getInterval());
  }

  @Test
  @DisplayName("A device code is consumed only once")
  void consume_once() {
    adapter.create(pending("device-1", "USER-1"));
    AuthenticationData auth = new AuthenticationData();
    auth.setUsername("alice");
    adapter.approve("device-1", auth);

    Assertions.assertTrue(adapter.consume("device-1"));
    Assertions.assertFalse(adapter.consume("device-1"), "A code can not be exchanged twice");
  }
}
